using System.ComponentModel;
using ModelContextProtocol.Server;
using Microsoft.Extensions.Logging;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class FetchDataTool
{
    [McpServerTool("fetch_data"), Description("Fetches data from an external API endpoint.")]
    public static async Task<string> FetchDataAsync(
        HttpClient httpClient,
        ILogger<FetchDataTool> logger,
        [Description("The API endpoint path to fetch (e.g. \"/posts/1\").")] string path,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching data from {Path}", path);

        var response = await httpClient.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        var content = await response.Content.ReadAsStringAsync(cancellationToken);
        logger.LogInformation("Received {Length} chars from {Path}", content.Length, path);

        return content;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Generates a concise summary of the provided text.")]
    public static IEnumerable<ChatMessage> Summarize(
        [Description("The text content to summarize.")] string text,
        [Description("Target length: 'short', 'medium', or 'long'.")] string length = "medium")
    {
        var systemInstruction = length switch
        {
            "short" => "Summarize the following text in 1-2 sentences.",
            "long" => "Provide a detailed summary of the following text, preserving key points and nuances.",
            _ => "Summarize the following text in a concise paragraph."
        };

        yield return new ChatMessage(ChatMessageRole.User,
            $"{systemInstruction}\n\n---\n\n{text}");
    }
}

