using System.ComponentModel;
using ModelContextProtocol.Server;
using Microsoft.Extensions.Logging;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class FetchDataTool
{
    [McpServerTool("fetch_data"), Description("Fetches data from an external API endpoint.")]
    public static async Task<string> FetchDataAsync(
        HttpClient httpClient,
        ILogger<FetchDataTool> logger,
        [Description("The API endpoint path to fetch (e.g. \"/posts/1\").")] string path,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching data from {Path}", path);

        var response = await httpClient.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        var content = await response.Content.ReadAsStringAsync(cancellationToken);
        logger.LogInformation("Received {Length} chars from {Path}", content.Length, path);

        return content;
    }
}

