using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt(Name = "summarize"), Description("Generates a concise summary of the provided text.")]
    public static IEnumerable<PromptMessage> Summarize(
        [Description("The text content to summarize.")] string text,
        [Description("Target length: 'short', 'medium', or 'long'.")] string length = "medium")
    {
        var systemInstruction = length switch
        {
            "short" => "Summarize the following text in 1-2 sentences.",
            "long" => "Provide a detailed summary of the following text, preserving key points and nuances.",
            _ => "Summarize the following text in a concise paragraph."
        };

        yield return new PromptMessage
        {
            Role = Role.User,
            Content = new ContentBlock { Text = $"{systemInstruction}\n\n---\n\n{text}" }
        };
    }
}

